    // Check if the value has already been computed
    if (dp[x] !== -1) {
        tv.onHover(`From DP : ${dp[x]}`, ok);
        return dp[x];
    }

    const tmp = fib(x - 1, ok) + fib(x - 2, ok);
    dp[x] = tmp; // Cache the computed value
    tv.onHover(String(tmp), ok);
    return tmp;
}

